void array_value(int t[],int n){//to initialise the array
    for(int i=0;i<n;i++){
        scanf("%d",&t[i]);
    }
}
int main(){
	int n,m;
	scanf("%d",&n);
	int A[n];
	array_value(A,n);
	scanf("%d",&m);
	int B[m],C[m+n];
    array_value(B,m);
    for(int i=0;i<(m+n);i++){
        if(i<n)
            C[i]=A[i];
        else
            C[i]=B[i-n];
    }
    for(int i=0;i<(m+n);i++){
        for(int j=i+1;j<(m+n);j++){
            if(C[i]>C[j]){
                int swap=C[i];
                C[i]=C[j];
                C[j]=swap;
            }
        }
    }
    for(int i=0;i<(m+n);i++)
        printf("%d/n",C[i]);
	return 0;
}

