void merge_array(int A[20],int sizeA,int B[20],int sizeB)
{
    int C[40],sizeC=sizeA+sizeB,i=0,markA=0,markB=0;
    while(markA<sizeA&&markB<sizeB)
    {
        if(A[markA]<B[markB])
        {
            C[i]=A[markA];
            markA++;
            i++;
        }
        else
        {
            C[i]=B[markB];
            markB++;
            i++;
        }
    }

    if(markA==sizeA)
    {
        for(;i<sizeC;i++)
        {
            C[i]=B[i];
        }
    }
    if(markB==sizeB)
    {
        for(;i<sizeC;i++)
        {
            C[i]=A[i];
        }
    }
    for(i=0;i<sizeC;i++)
	{
	    printf("%d\n",C[i]);
	}
}
