#include <stdio.h>

void merge (int A1[], int l1, int A2[], int l2, int A[])
{
    int i=0,j=0,count=0;
    while (count<l1+l2)
    {
        if (A1[i]<A2[j])
        A[count++]=A1[i++];
        if (A2[j]<A1[i])
        A[count++]=A2[j++];
        if (A1[i]==A2[j])
        {
            A[count++]=A1[i++];
            j++;
        }
        if (i==l1)
        {
            while (j!=l2)
            A[count++]=A2[j++];
        }
        if (j==l2)
        {
            while (i!=l1)
            A[count++]=A1[i++];
        }
    }
}

